    @QueryHandler
    public List<Visualization> handle( FindAllVisualizationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindVisualization,
 * but only if the id matches
 *
 * @param		entity	Visualization
 */
	protected void emitFindVisualization( Visualization entity ) {
		LOGGER.info("handling emitFindVisualization" );
		
	    queryUpdateEmitter.emit(FindVisualizationQuery.class,
	                            query -> query.getFilter().getVisualizationId().equals(entity.getVisualizationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllVisualization
	 * 
	 * @param		entity	Visualization
	 */
	protected void emitFindAllVisualization( Visualization entity ) {
		LOGGER.info("handling emitFindAllVisualization" );
		
	    queryUpdateEmitter.emit(FindAllVisualizationQuery.class,
	                            query -> true,
	                            entity);
	}

